import heapq

def top_k_frequent(nums, k):
    freq = {}
    for v in nums:
        freq[v] = freq.get(v, 0) + 1
    shortlist = []  # min-heap of (frequency, value)
    for value, count in freq.items():
        heapq.heappush(shortlist, (count, value))
        if len(shortlist) > k:
            heapq.heappop(shortlist)
    return [value for _, value in shortlist]

