import java.util.*;

class Solution {
    public int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : nums) freq.merge(v, 1, Integer::sum);
        PriorityQueue<int[]> shortlist = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
            shortlist.offer(new int[]{e.getValue(), e.getKey()});
            if (shortlist.size() > k) shortlist.poll();
        }
        return shortlist.stream().mapToInt(p -> p[1]).toArray();
    }
}
